{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE Bot_csat as ( SELECT conversation_id, message_data.value:created_time::timestamp AS created_time, message_part.value:text:content::string AS message_content, message_data.value:conversation_id::string AS conversation_id2 FROM freshchat_msg_final_v4_conversations_by_id, LATERAL FLATTEN(input => messages) AS message_data, LATERAL FLATTEN(input => message_data.value:message_parts) AS message_part, WHERE message_data.value:actor_type::string = \'user\' AND message_part.value:text:content::string IN (\'Very Happy\', \'Happy\', \'Not Satisfied\', \'Sad\', \'Extremely Sad\') ); CREATE OR REPLACE TABLE snitch_db.maplemonk.contactratereasons AS ( WITH messages_exploded AS ( SELECT m.value:conversation_id::string AS conversation_id, m.value:created_time::timestamp AS created_time, m.value:actor_type::string AS actor_type, m.value:message_parts AS message_parts FROM freshchat_msg_final_v3_conversations_by_id fc, LATERAL FLATTEN(input => fc.MESSAGES) m ) SELECT DISTINCT t.conversation_id, t.created_time, t.content_msg FROM ( SELECT me.*, ROW_NUMBER() OVER (PARTITION BY me.conversation_id ORDER BY me.created_time ASC) AS rn, me.message_parts[0]:text:content::string AS content_msg FROM messages_exploded me WHERE me.actor_type = \'user\' ) t WHERE t.rn = 2 ); CREATE OR REPLACE TABLE Bot_csat_v2 AS ( SELECT A.conversation_id AS conversation_id_A, A.created_time AS user_message_time, A.message_content, B.conversation_id AS conversation_id_B, B.created_time AS previous_message_time, B.user_content, B.previous_content FROM ( SELECT conversation_id, message_data.value:created_time::timestamp AS created_time, message_part.value:text:content::string AS message_content FROM freshchat_msg_final_v4_conversations_by_id, LATERAL FLATTEN(input => messages) AS message_data, LATERAL FLATTEN(input => message_data.value:message_parts) AS message_part WHERE message_data.value:actor_type::string = \'user\' AND message_part.value:text:content::string IN (\'Very Happy\', \'Happy\', \'Not Satisfied\', \'Sad\', \'Extremely Sad\') ) AS A LEFT JOIN ( WITH messages_flat AS ( SELECT ROW_NUMBER() OVER (PARTITION BY t0.conversation_id ORDER BY t1.value:created_time::timestamp) AS msg_order, t0.conversation_id, t1.value:actor_type::string AS actor_type, TRIM(REGEXP_REPLACE(t1.value:message_parts[0]:text:content::string, \'[\n\r\t]+\', \'\')) AS content, t1.value:created_time::timestamp AS created_time FROM freshchat_msg_final_v4_conversations_by_id t0, LATERAL FLATTEN(input => t0.messages) t1 ) SELECT mf1.conversation_id, mf1.created_time, mf1.content AS user_content, mf2.content AS previous_content FROM messages_flat mf1 JOIN messages_flat mf2 ON mf1.conversation_id = mf2.conversation_id AND mf1.msg_order = mf2.msg_order + 1 WHERE mf1.actor_type = \'user\' AND REGEXP_LIKE(mf2.content, \'How can I help you today.*\', \'i\') ) AS B ON A.conversation_id = B.conversation_id ); CREATE OR REPLACE TABLE snitch_db.maplemonk.Order_Over_Issues_real_v5 AS ( WITH base AS ( SELECT \"External ticket Id\", TO_TIMESTAMP_NTZ( \'2025-06-16 12:13:25 PM\', \'YYYY-MM-DD HH12:MI:SS AM\' ) AS created_ts, status, flow FROM maplemonk.freshchat_bot_conversations WHERE status = \'Closed\' AND flow NOT IN (\'Resolve - Campaigns flow\', \'Talk to agent\') AND TO_TIMESTAMP_NTZ( \'2025-06-16 12:13:25 PM\', \'YYYY-MM-DD HH12:MI:SS AM\' ) >= \'2024-10-01 00:00:00\' ), first_user_msg AS ( SELECT DISTINCT t.conversation_id, t.created_time, t.content_msg FROM ( SELECT me.value:conversation_id::string AS conversation_id, me.value:created_time::timestamp AS created_time, ROW_NUMBER() OVER (PARTITION BY me.value:conversation_id::string ORDER BY me.value:created_time) AS rn, me.value:message_parts[0]:text:content::string AS content_msg FROM freshchat_msg_final_v4_conversations_by_id fc, LATERAL FLATTEN(input => fc.MESSAGES) me WHERE me.value:actor_type::string = \'user\' ) t WHERE t.rn = 3 ) SELECT b.\"External ticket Id\", b.created_ts AS \"Created date\", b.status, b.flow, f.created_time, f.content_msg FROM base b LEFT JOIN first_user_msg f ON b.\"External ticket Id\" = f.conversation_id); CREATE OR REPLACE TABLE freshchat_bot_conversations AS ( SELECT BOT, FLOW, STATUS, CHANNEL, CUSTOMER, LANGUAGE, \"Bot version\", \"Landing URL\", \"Created date\", \"Conversation id\", \"Last updated at\", \"Resolution type\", \"Conversation hash\", \"External ticket Id\", \"Agent handover Type\", \"Last traversed dialog\", _AIRBYTE_AB_ID, _AIRBYTE_EMITTED_AT, _AIRBYTE_NORMALIZED_AT, _AIRBYTE_FRESHCHAT_BOT_CONVERSATIONS_HASHID FROM freshchat_bot_conversations UNION ALL SELECT BOT, FLOW, STATUS, CHANNEL, CUSTOMER, LANGUAGE, \"Bot version\", \"Landing URL\", LEFT(\"Created date\", 19) AS \"Created date\", \"Conversation id\", LEFT(\"Last updated at\",19) as \"Last updated at\", \"Resolution type\", \"Conversation hash\", \"External ticket Id\", \"Agent handover Type\", \"Last traversed dialog\", _AIRBYTE_AB_ID, _AIRBYTE_EMITTED_AT, _AIRBYTE_NORMALIZED_AT, _AIRBYTE_FRESHCHAT_NEW_BOT_CONVERSATIONS_HASHID FROM freshchat_new_bot_conversations);",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            